/***
 * Defines the base class and methods for Spell Effects, Groups, and Shapes.
 *
 * isEnabled - Gets whether a component is enabled from the config.
 *
 * getArcanaCost - gets the arcana cost
 *
 * singleCastOnly - returns if a component can only proc once when spell is cast.
 *
 * getArcanaCostAsString - makes the arcana cost printable in the console. Testing Purposes only.
 *
 * getTexture - Gets the texture and returns it as a variable.
 *
 * getTranslationKey - Used to return the id of individual objects when making lang files.
 *
 * getName - Used to return a human-readable name for an object.
 */


package dev.cammiescorner.arcanus.api.spell.components;

import com.mojang.serialization.Codec;
import dev.cammiescorner.arcanus.Arcanus;
import dev.cammiescorner.arcanus.api.ArcanusRegistries;
import dev.cammiescorner.arcanus.api.arcana.PrimalArcana;
import dev.cammiescorner.arcanus.common.registry.ArcanusComponents;
import dev.cammiescorner.arcanus.common.registry.ArcanusSpellComponents;
import dev.upcraft.sparkweave.api.registry.RegistryHelper;
import it.unimi.dsi.fastutil.objects.Object2DoubleArrayMap;
import it.unimi.dsi.fastutil.objects.Object2DoubleMap;
import net.minecraft.ChatFormatting;
import net.minecraft.Util;
import net.minecraft.network.RegistryFriendlyByteBuf;
import net.minecraft.network.chat.Component;
import net.minecraft.network.chat.MutableComponent;
import net.minecraft.network.codec.ByteBufCodecs;
import net.minecraft.network.codec.StreamCodec;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.entity.player.Player;

import java.util.function.Supplier;

public class SpellComponent {
	public static final Codec<SpellComponent> CODEC = Codec.lazyInitialized(() -> RegistryHelper.getBuiltinRegistry(ArcanusRegistries.SPELL_COMPONENT).byNameCodec());
	public static final StreamCodec<RegistryFriendlyByteBuf, SpellComponent> STREAM_CODEC = ByteBufCodecs.registry(ArcanusRegistries.SPELL_COMPONENT);
	public static final String DISABLED_TRANSLATION_KEY = Util.makeDescriptionId("arcanus.spell_component", Arcanus.id("disabled"));
	private static final MutableComponent DISABLED_TRANSLATED_NAME = Component.translatable(DISABLED_TRANSLATION_KEY).withStyle(ChatFormatting.OBFUSCATED);
	private final Supplier<Boolean> isEnabled;
	private final Supplier<Object2DoubleArrayMap<PrimalArcana>> arcanaCost;
	private final Supplier<Boolean> activatesOnce;
	private String translationKey;
	private ResourceLocation texture;

	public SpellComponent(Supplier<Boolean> isEnabled, Supplier<Object2DoubleArrayMap<PrimalArcana>> arcanaCost, Supplier<Boolean> activatesOnce) {
		this.isEnabled = isEnabled;
		this.arcanaCost = arcanaCost;
		this.activatesOnce = activatesOnce;
	}

	public boolean isEnabled() {
		return isEnabled.get();
	}

	public Object2DoubleMap<PrimalArcana> getArcanaCost() {
		return arcanaCost.get().clone();
	}

	public boolean singleCastOnly() {
		return activatesOnce.get();
	}

	public String getArcanaCostAsString(PrimalArcana primalArcana) {
		return Arcanus.format(getArcanaCost().getDouble(primalArcana));
	}

	public ResourceLocation getTexture(Player player) {
		if(!ArcanusComponents.knowsSpellComponents(player, this))
			return Arcanus.id("unknown_component.png").withPrefix("textures/spell_components/");

		if(texture == null) {
			ResourceLocation id = ArcanusSpellComponents.REGISTRY.getKey(this);
			String extra = "";

			if(this instanceof SpellShape)
				extra = "shapes/";
			if(this instanceof SpellEffect)
				extra = "effects/";

			texture = id.withPrefix("textures/spell_components/" + extra).withSuffix(".png");//ResourceLocation.fromNamespaceAndPath(id.getNamespace(), "" + extra + id.getPath() + ".png");
		}

		return texture;
	}

	public String translationKey() {
		if(translationKey == null)
			translationKey = Util.makeDescriptionId("arcanus.spell_component", ArcanusSpellComponents.REGISTRY.getKey(this));

		return translationKey;
	}

	public MutableComponent getName() {
		if(!isEnabled())
			return DISABLED_TRANSLATED_NAME;

		return Component.translatable(translationKey());
	}
}

package dev.cammiescorner.arcanus.common.component.entity;

import com.mojang.serialization.Codec;
import dev.cammiescorner.arcanus.api.spell.components.SpellComponent;
import dev.cammiescorner.arcanus.common.registry.ArcanusComponents;
import dev.cammiescorner.arcanus.common.registry.ArcanusSpellComponents;
import net.minecraft.core.HolderLookup;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.NbtOps;
import net.minecraft.world.entity.LivingEntity;
import org.ladysnake.cca.api.v3.component.sync.AutoSyncedComponent;

import java.util.ArrayList;
import java.util.List;

public class KnownSpellComponentsComponent implements AutoSyncedComponent {
	private static final Codec<List<SpellComponent>> CODEC = SpellComponent.CODEC.listOf();
	private final List<SpellComponent> knownComponents = new ArrayList<>();
	private final LivingEntity entity;

	public KnownSpellComponentsComponent(LivingEntity entity) {
		this.entity = entity;
		knownComponents.add(ArcanusSpellComponents.EMPTY.get());
	}

	@Override
	public void readFromNbt(CompoundTag tag, HolderLookup.Provider registryLookup) {
		knownComponents.clear();
		knownComponents.addAll(CODEC.parse(registryLookup.createSerializationContext(NbtOps.INSTANCE), tag.get("KnownSpellComponents")).getOrThrow());
	}

	@Override
	public void writeToNbt(CompoundTag tag, HolderLookup.Provider registryLookup) {
		tag.put("KnownSpellComponents", CODEC.encodeStart(registryLookup.createSerializationContext(NbtOps.INSTANCE), knownComponents).getOrThrow());
	}

	public List<SpellComponent> getKnownComponents() {
		return List.copyOf(knownComponents);
	}

	public void learnSpellComponent(SpellComponent component) {
		if(knownComponents.contains(component))
			return;

		knownComponents.add(component);
		ArcanusComponents.KNOWN_SPELL_COMPONENTS_COMPONENT.sync(entity);
	}

	public void forgetSpellComponent(SpellComponent component) {
		if(!knownComponents.contains(component))
			return;

		knownComponents.remove(component);
		ArcanusComponents.KNOWN_SPELL_COMPONENTS_COMPONENT.sync(entity);
	}
}

package dev.cammiescorner.arcanus.common.item;

import dev.cammiescorner.arcanus.api.spell.components.SpellComponent;
import dev.cammiescorner.arcanus.common.registry.ArcanusComponents;
import dev.cammiescorner.arcanus.common.registry.ArcanusDataComponents;
import dev.cammiescorner.arcanus.common.registry.ArcanusSpellComponents;
import dev.cammiescorner.arcanus.common.util.TranslationKeys;
import net.minecraft.ChatFormatting;
import net.minecraft.network.chat.Component;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.InteractionResultHolder;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.TooltipFlag;
import net.minecraft.world.level.Level;

import java.util.List;

public class ScrollOfKnowledgeItem extends Item {
	public ScrollOfKnowledgeItem() {
		super(new Item.Properties().stacksTo(1).component(ArcanusDataComponents.SPELL_COMPONENT.get(), ArcanusSpellComponents.EMPTY.get()));
	}

	@Override
	public InteractionResultHolder<ItemStack> use(Level level, Player user, InteractionHand hand) {
		// TODO this is temporary to make it easy to learn spell components, until rites are implemented
		//  then we just display a screen with a button for creative users to auto learn the component

		ItemStack stack = user.getItemInHand(hand);
		SpellComponent spellComponent = stack.getOrDefault(ArcanusDataComponents.SPELL_COMPONENT.get(), ArcanusSpellComponents.EMPTY.get());

		if(ArcanusComponents.knowsSpellComponents(user, spellComponent)) {
			user.displayClientMessage(Component.translatable(TranslationKeys.USE_SCROLL_ALREADY_KNOW).withStyle(ChatFormatting.RED), true);

			return InteractionResultHolder.fail(stack);
		}

		if(!spellComponent.isEnabled()) {
			user.displayClientMessage(Component.translatable(TranslationKeys.USE_SCROLL_DISABLED_COMPONENT).withStyle(ChatFormatting.RED), true);

			return InteractionResultHolder.fail(stack);
		}

		ArcanusComponents.learnSpellComponents(user, spellComponent);

		user.displayClientMessage(Component.translatable(TranslationKeys.USE_SCROLL_SUCCESS).withStyle(ChatFormatting.LIGHT_PURPLE), true);

		return InteractionResultHolder.success(stack);
	}

	@Override
	public void appendHoverText(ItemStack stack, TooltipContext context, List<Component> tooltipComponents, TooltipFlag tooltipFlag) {
		SpellComponent component = stack.getOrDefault(ArcanusDataComponents.SPELL_COMPONENT.get(), ArcanusSpellComponents.EMPTY.get());

		if(component.isEnabled())
			tooltipComponents.add(component.getName().withStyle(ChatFormatting.GOLD));
		else
			tooltipComponents.add(Component.translatable(TranslationKeys.DISABLED_COMPONENT).withStyle(ChatFormatting.RED));
	}
}

package dev.cammiescorner.arcanus.common.networking.serverbound;

import commonnetwork.networking.data.PacketContext;
import dev.cammiescorner.arcanus.Arcanus;
import dev.cammiescorner.arcanus.api.arcana.PrimalArcana;
import dev.cammiescorner.arcanus.api.spell.Pattern;
import dev.cammiescorner.arcanus.api.spell.Spell;
import dev.cammiescorner.arcanus.api.spell.components.SpellGroup;
import dev.cammiescorner.arcanus.common.data.ArcanusItemTags;
import dev.cammiescorner.arcanus.common.data_component.SpellBookComponent;
import dev.cammiescorner.arcanus.common.item.StaffItem;
import dev.cammiescorner.arcanus.common.registry.ArcanusAttributes;
import dev.cammiescorner.arcanus.common.registry.ArcanusComponents;
import dev.cammiescorner.arcanus.common.registry.ArcanusDataComponents;
import dev.cammiescorner.arcanus.common.util.ArcanusHelper;
import dev.emi.trinkets.api.TrinketComponent;
import dev.emi.trinkets.api.TrinketsApi;
import net.minecraft.ChatFormatting;
import net.minecraft.core.Holder;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraft.network.chat.Component;
import net.minecraft.network.codec.StreamCodec;
import net.minecraft.network.protocol.common.custom.CustomPacketPayload;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;

import java.util.ArrayList;
import java.util.List;
import java.util.Optional;

import static dev.cammiescorner.arcanus.common.util.TranslationKeys.*;

public record ServerboundSyncPatternPacket(List<Pattern> patterns, boolean castSpell) implements CustomPacketPayload {
	public static final CustomPacketPayload.Type<ServerboundSyncPatternPacket> TYPE = new CustomPacketPayload.Type<>(Arcanus.id("sync_pattern"));
	public static final StreamCodec<? extends FriendlyByteBuf, ServerboundSyncPatternPacket> CODEC = StreamCodec.of((buffer, packet) -> {
		buffer.writeCollection(packet.patterns, FriendlyByteBuf::writeEnum);
		buffer.writeBoolean(packet.castSpell);
	}, buffer -> {
		List<Pattern> patterns = buffer.readCollection(ArrayList::new, buf -> buf.readEnum(Pattern.class));
		boolean castSpell = buffer.readBoolean();

		return new ServerboundSyncPatternPacket(patterns, castSpell);
	});

	public static void handle(PacketContext<ServerboundSyncPatternPacket> context) {
		ServerPlayer player = context.sender();
		List<Pattern> pattern = context.message().patterns();

		ArcanusComponents.setPattern(player, pattern);

		if(pattern.size() >= 3 && context.message().castSpell()) {
			ItemStack stack = player.getMainHandItem();

			if(stack.getItem() instanceof StaffItem staff) {
				Optional<TrinketComponent> optional = TrinketsApi.getTrinketComponent(player);

				if(optional.isPresent()) {
					ItemStack spellBook = ArcanusHelper.getActiveSpellBook(player);
					SpellBookComponent spells = spellBook.getOrDefault(ArcanusDataComponents.SPELL_BOOK.get(), SpellBookComponent.empty());
					int index = ArcanusHelper.getSpellIndex(pattern);

					if(player.getCooldowns().getCooldownPercent(staff, 1f) == 0) {
						Spell spell = spells.getSpell(index);

						if(!spell.getComponentGroups().stream().flatMap(SpellGroup::getAllComponents).allMatch(spellComponent -> ArcanusComponents.knowsSpellComponents(player, spellComponent))) {
							player.displayClientMessage(Component.translatable(SPELL_UNKNOWN_SPELL_COMPONENTS).withStyle(ChatFormatting.RED, ChatFormatting.ITALIC), true);
							return;
						}

						if(spell.getComponentGroups().stream().flatMap(SpellGroup::getAllComponents).count() > ArcanusComponents.maxSpellSize()) {
							player.displayClientMessage(Component.translatable(SPELL_TOO_MANY_COMPONENTS), true);
							return;
						}

						for(PrimalArcana primalArcana : spell.getArcanaCost().keySet()) {
							if(!player.isCreative() && !ArcanusComponents.drainArcana(player, primalArcana, spell.getArcanaCost().getDouble(primalArcana), false)) {
								player.displayClientMessage(Component.translatable(SPELL_NOT_ENOUGH_MANA).withStyle(ChatFormatting.RED, ChatFormatting.ITALIC), true);
								return;
							}
						}

						ArcanusComponents.setPattern(player, ArcanusHelper.getSpellPattern(index));
						ArcanusComponents.setLastCastTime(player, player.level().getGameTime());
						spell.cast(player, player.serverLevel(), stack);
						player.displayClientMessage(Component.translatable(spell.getName()).withStyle(ChatFormatting.GREEN), true);

						for(Holder<Item> holder : BuiltInRegistries.ITEM.getTagOrEmpty(ArcanusItemTags.STAVES))
							player.getCooldowns().addCooldown(holder.value(), (int) (spell.getCoolDown() * player.getAttributeValue(ArcanusAttributes.SPELL_COOL_DOWN.holder())));
					}
				}
			}
		}
	}

	@Override
	public Type<? extends CustomPacketPayload> type() {
		return TYPE;
	}
}

package dev.cammiescorner.arcanus.common.registry;

import dev.cammiescorner.arcanus.Arcanus;
import dev.cammiescorner.arcanus.ArcanusConfig;
import dev.cammiescorner.arcanus.api.arcana.PrimalArcana;
import dev.cammiescorner.arcanus.api.spell.Pattern;
import dev.cammiescorner.arcanus.api.spell.components.SpellComponent;
import dev.cammiescorner.arcanus.common.block.entities.AbstractMagicBlockEntity;
import dev.cammiescorner.arcanus.common.component.MagicColorComponent;
import dev.cammiescorner.arcanus.common.component.chunk.WardedBlocksComponent;
import dev.cammiescorner.arcanus.common.component.color.GenericMagicColorComponent;
import dev.cammiescorner.arcanus.common.component.color.PlayerMagicColorComponent;
import dev.cammiescorner.arcanus.common.component.entity.*;
import dev.cammiescorner.arcanus.common.component.level.PocketDimensionComponent;
import dev.cammiescorner.arcanus.common.entity.magic.*;
import dev.upcraft.sparkweave.api.color.Color;
import net.minecraft.core.BlockPos;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.chunk.ChunkAccess;
import net.minecraft.world.level.chunk.EmptyLevelChunk;
import net.minecraft.world.phys.Vec3;
import org.jetbrains.annotations.Nullable;
import org.ladysnake.cca.api.v3.block.BlockComponentFactoryRegistry;
import org.ladysnake.cca.api.v3.block.BlockComponentInitializer;
import org.ladysnake.cca.api.v3.chunk.ChunkComponentFactoryRegistry;
import org.ladysnake.cca.api.v3.chunk.ChunkComponentInitializer;
import org.ladysnake.cca.api.v3.component.Component;
import org.ladysnake.cca.api.v3.component.ComponentKey;
import org.ladysnake.cca.api.v3.component.ComponentRegistry;
import org.ladysnake.cca.api.v3.entity.EntityComponentFactoryRegistry;
import org.ladysnake.cca.api.v3.entity.EntityComponentInitializer;
import org.ladysnake.cca.api.v3.entity.RespawnCopyStrategy;
import org.ladysnake.cca.api.v3.scoreboard.ScoreboardComponentFactoryRegistry;
import org.ladysnake.cca.api.v3.scoreboard.ScoreboardComponentInitializer;

import java.util.Arrays;
import java.util.List;
import java.util.Map;
import java.util.UUID;

public class ArcanusComponents implements BlockComponentInitializer, ChunkComponentInitializer, EntityComponentInitializer, ScoreboardComponentInitializer {
	public static final ComponentKey<MagicColorComponent> MAGIC_COLOR = createComponent("magic_color", MagicColorComponent.class);

	// ----- Scoreboard Components ----- \\
	public static final ComponentKey<PocketDimensionComponent> POCKET_DIMENSION_COMPONENT = createComponent("pocket_dimension", PocketDimensionComponent.class);

	// ----- Chunk Components ----- \\
	public static final ComponentKey<WardedBlocksComponent> WARDED_BLOCKS_COMPONENT = createComponent("warded_blocks", WardedBlocksComponent.class);

	// ----- Entity Components ----- \\
	public static final ComponentKey<KnownSpellComponentsComponent> KNOWN_SPELL_COMPONENTS_COMPONENT = createComponent("known_spell_components", KnownSpellComponentsComponent.class);
	public static final ComponentKey<ArcanaComponent> ARCANA_COMPONENT = createComponent("arcana", ArcanaComponent.class);
	public static final ComponentKey<SpellCoolDownComponent> SPELL_COOL_DOWN_COMPONENT = createComponent("spell_cool_down", SpellCoolDownComponent.class);
	public static final ComponentKey<CastingComponent> CASTING_COMPONENT = createComponent("casting", CastingComponent.class);
	public static final ComponentKey<PatternComponent> PATTERN_COMPONENT = createComponent("casting_pattern", PatternComponent.class);
	public static final ComponentKey<LastCastTimeComponent> LAST_CAST_TIME_COMPONENT = createComponent("last_cast_time", LastCastTimeComponent.class);
	public static final ComponentKey<StunComponent> STUN_COMPONENT = createComponent("stun", StunComponent.class);
	public static final ComponentKey<BoltTargetComponent> BOLT_TARGET = createComponent("bolt_target", BoltTargetComponent.class);
	public static final ComponentKey<PocketDimensionPortalComponent> POCKET_DIMENSION_PORTAL_COMPONENT = createComponent("pocket_dimension_portal", PocketDimensionPortalComponent.class);
	public static final ComponentKey<StockpileOrbsComponent> STOCKPILE_ORB_COMPONENT = createComponent("stockpile_orbs", StockpileOrbsComponent.class);
	public static final ComponentKey<MagicOrbComponent> MAGIC_ORB_COMPONENT = createComponent("magic_orb", MagicOrbComponent.class);
	public static final ComponentKey<PortalCoolDownComponent> PORTAL_COOL_DOWN_COMPONENT = createComponent("portal_cool_down", PortalCoolDownComponent.class);

	@Override
	public void registerBlockComponentFactories(BlockComponentFactoryRegistry registry) {
		registry.beginRegistration(AbstractMagicBlockEntity.class, MAGIC_COLOR)
			.impl(GenericMagicColorComponent.class)
			.end(GenericMagicColorComponent::new);
	}

	@Override
	public void registerChunkComponentFactories(ChunkComponentFactoryRegistry registry) {
		registry.register(WARDED_BLOCKS_COMPONENT, WardedBlocksComponent::new);
	}

	@Override
	public void registerEntityComponentFactories(EntityComponentFactoryRegistry registry) {
		registry.beginRegistration(Player.class, KNOWN_SPELL_COMPONENTS_COMPONENT).respawnStrategy(RespawnCopyStrategy.ALWAYS_COPY).end(KnownSpellComponentsComponent::new);
		registry.beginRegistration(LivingEntity.class, ARCANA_COMPONENT).respawnStrategy(RespawnCopyStrategy.ALWAYS_COPY).end(ArcanaComponent::new);
		registry.beginRegistration(LivingEntity.class, SPELL_COOL_DOWN_COMPONENT).respawnStrategy(RespawnCopyStrategy.ALWAYS_COPY).end(SpellCoolDownComponent::new);
		registry.beginRegistration(Player.class, CASTING_COMPONENT).respawnStrategy(RespawnCopyStrategy.NEVER_COPY).end(CastingComponent::new);
		registry.beginRegistration(Player.class, PATTERN_COMPONENT).respawnStrategy(RespawnCopyStrategy.NEVER_COPY).end(PatternComponent::new);
		registry.beginRegistration(Player.class, POCKET_DIMENSION_PORTAL_COMPONENT).respawnStrategy(RespawnCopyStrategy.ALWAYS_COPY).end(PocketDimensionPortalComponent::new);
		registry.beginRegistration(LivingEntity.class, LAST_CAST_TIME_COMPONENT).respawnStrategy(RespawnCopyStrategy.NEVER_COPY).end(LastCastTimeComponent::new);
		registry.beginRegistration(LivingEntity.class, STUN_COMPONENT).respawnStrategy(RespawnCopyStrategy.NEVER_COPY).end(StunComponent::new);
		registry.beginRegistration(LivingEntity.class, BOLT_TARGET).respawnStrategy(RespawnCopyStrategy.NEVER_COPY).end(BoltTargetComponent::new);
		registry.beginRegistration(LivingEntity.class, STOCKPILE_ORB_COMPONENT).respawnStrategy(RespawnCopyStrategy.NEVER_COPY).end(StockpileOrbsComponent::new);
		registry.beginRegistration(LivingEntity.class, MAGIC_ORB_COMPONENT).respawnStrategy(RespawnCopyStrategy.NEVER_COPY).end(MagicOrbComponent::new);
		registry.beginRegistration(Entity.class, PORTAL_COOL_DOWN_COMPONENT).respawnStrategy(RespawnCopyStrategy.ALWAYS_COPY).end(PortalCoolDownComponent::new);

		List.of(
			StockpileOrb.class,
			AreaOfEffect.class,
			Beam.class,
			MagicOrb.class,
			Missile.class,
			MagicRune.class,
			ManaShield.class,
			PocketDimensionPortal.class,
			Smite.class,
			TemporalDilationField.class
		).forEach(type ->
			registry.beginRegistration(type, MAGIC_COLOR)
				.impl(GenericMagicColorComponent.class)
				.end(GenericMagicColorComponent::new)
		);
		registry.registerForPlayers(MAGIC_COLOR, PlayerMagicColorComponent::new, RespawnCopyStrategy.NEVER_COPY);
	}

	private static <T extends Component> ComponentKey<T> createComponent(String name, Class<T> component) {
		return ComponentRegistry.getOrCreate(Arcanus.id(name), component);
	}

	@Nullable
	private static WardedBlocksComponent getWardedBlocksComponent(Level world, BlockPos pos) {
		ChunkAccess chunk = world.getChunk(pos);
		return !(chunk instanceof EmptyLevelChunk) ? chunk.getComponent(WARDED_BLOCKS_COMPONENT) : null;
	}

	// ----- Helper Methods ----- //
	public static void addWardedBlock(Player player, BlockPos pos) {
		WardedBlocksComponent component = getWardedBlocksComponent(player.level(), pos);
		if(component != null)
			component.addWardedBlock(player, pos);
	}

	public static void removeWardedBlock(Player player, BlockPos pos) {
		WardedBlocksComponent component = getWardedBlocksComponent(player.level(), pos);
		if(component != null)
			component.removeWardedBlock(player, pos);
	}

	public static boolean isOwnerOfBlock(Player player, BlockPos pos) {
		WardedBlocksComponent component = getWardedBlocksComponent(player.level(), pos);
		return component != null && component.isOwnerOfBlock(player, pos);
	}

	public static boolean isBlockWarded(Level world, BlockPos pos) {
		WardedBlocksComponent component = getWardedBlocksComponent(world, pos);
		return component != null && component.isBlockWarded(pos);
	}

	public static Map<BlockPos, java.util.UUID> getWardedBlocks(ChunkAccess chunk) {
		if(chunk instanceof EmptyLevelChunk)
			return Map.of();

		return chunk.getComponent(WARDED_BLOCKS_COMPONENT).getWardedBlocks();
	}

	public static double getMaxArcana(LivingEntity entity, PrimalArcana primalArcana) {
		return primalArcana.getMaxArcana(entity);
	}

	public static double getArcanaLock(LivingEntity entity) {
		return entity.getComponent(ARCANA_COMPONENT).getArcanaLock();
	}

	public static double getTrueMaxArcana(LivingEntity entity, PrimalArcana primalArcana) {
		return entity.getComponent(ARCANA_COMPONENT).getTrueMaxArcana(primalArcana);
	}

	public static double getArcana(LivingEntity entity, PrimalArcana primalArcana) {
		return entity.getComponent(ARCANA_COMPONENT).getArcana(primalArcana);
	}

	public static void setArcana(LivingEntity entity, PrimalArcana primalArcana, double amount) {
		entity.getComponent(ARCANA_COMPONENT).setArcana(primalArcana, amount);
	}

	public static boolean addArcana(LivingEntity entity, PrimalArcana primalArcana, double amount, boolean simulate) {
		return entity.getComponent(ARCANA_COMPONENT).addArcana(primalArcana, amount, simulate);
	}

	public static boolean drainArcana(LivingEntity entity, PrimalArcana primalArcana, double amount, boolean simulate) {
		return entity.getComponent(ARCANA_COMPONENT).drainArcana(primalArcana, amount, simulate);
	}

	public static List<SpellComponent> getKnownSpellComponents(Player player) {
		return player.getComponent(KNOWN_SPELL_COMPONENTS_COMPONENT).getKnownComponents();
	}

	public static boolean knowsAnySpellComponents(Player player) {
		List<SpellComponent> knownSpellComponents = getKnownSpellComponents(player);

		return knownSpellComponents.contains(ArcanusSpellComponents.EMPTY.get()) && knownSpellComponents.size() > 1;
	}

	public static boolean knowsSpellComponents(Player player, SpellComponent... components) {
		return getKnownSpellComponents(player).containsAll(Arrays.asList(components));
	}

	public static void learnSpellComponents(Player player, SpellComponent... components) {
		for(SpellComponent spellComponent : components)
			player.getComponent(KNOWN_SPELL_COMPONENTS_COMPONENT).learnSpellComponent(spellComponent);
	}

	public static void forgetSpellComponents(Player player, SpellComponent... components) {
		for(SpellComponent spellComponent : components)
			player.getComponent(KNOWN_SPELL_COMPONENTS_COMPONENT).forgetSpellComponent(spellComponent);
	}

	public static int maxSpellSize() {
		return ArcanusConfig.maxComponentsPerSpell;
	}

	public static boolean isCasting(LivingEntity entity) {
		return CASTING_COMPONENT.get(entity).isCasting();
	}

	public static void setCasting(LivingEntity entity, boolean casting) {
